import React from 'react';

const About = () => (
  <div className="text-center">
    <h1>Sasmita Ojha</h1>
    <p className="lead">UI/UX Designer | Graphic Designer | MERN Developer</p>
    <p>
      B.Tech in Computer Science (Balasore College of Engineering and Technology)<br />
      Passionate about creating intuitive and engaging digital experiences.
    </p>
  </div>
);

export default About;
